+
+// wrapDisplayWidth wraps s to lines no wider than width display cells. Embedded
+// '\n' characters are honored as paragraph boundaries: each paragraph is
+// sanitized (ANSI/control stripped) and wrapped independently. A paragraph that
+// wraps to nothing still contributes an empty line, preserving blank-line
+// structure between paragraphs.
+//
+// Returns nil for width <= 0 or empty input.
+func wrapDisplayWidth(s string, width int) []string {
+	if width <= 0 || s == "" {
+		return nil
+	}
+	paragraphs := strings.Split(s, "\n")
+	out := make([]string, 0, len(paragraphs))
+	for _, p := range paragraphs {
+		clean := sanitizeDisplayText(p)
+		if clean == "" {
+			out = append(out, "")
+			continue
+		}
+		wrapped := ansi.Wrap(clean, width, "")
+		out = append(out, strings.Split(wrapped, "\n")...)
+	}
+	return out
+}

1	// Package review — see env.go for package-level rationale.
2	package review
3	
4	import (
5		"strings"
6		"unicode"
7	
8		"github.com/charmbracelet/x/ansi"
9	)
10	
11	func stripANSI(s string) string {
12		return ansi.Strip(s)
13	}
14	
15	func sanitizeDisplayText(s string) string {
16		stripped := stripANSI(s)
17		return strings.Map(func(r rune) rune {
18			switch r {
19			case '\n', '\t':
20				return ' '
21			case '\r':
22				return -1
23			}
24			if unicode.IsControl(r) {
25				return -1
26			}
27			return r
28		}, stripped)
29	}
30	
31	func padDisplayWidth(s string, width int) string {
32		return padDisplayWidthWith(s, width, " ")
33	}
34	
35	func padDisplayWidthWith(s string, width int, pad string) string {
36		s = truncateDisplayWidth(s, width)
37		remaining := width - ansi.StringWidth(s)
38		if remaining <= 0 {
39			return s
40		}
41		if ansi.StringWidth(pad) != 1 {
42			return s + strings.Repeat(" ", remaining)
43		}
44		return s + strings.Repeat(pad, remaining)
45	}
46	
47	func truncateDisplayWidth(s string, width int) string {
48		if width <= 0 {
49			return ""
50		}
51		if ansi.StringWidth(s) <= width {
52			return s
53		}
54		if width == 1 {
55			return ansi.Truncate(s, width, "")
56		}
57		return ansi.Truncate(s, width, "…")
58	}
59	
60	// wrapDisplayWidth wraps s to lines no wider than width display cells. Embedded
61	// '\n' characters are honored as paragraph boundaries: each paragraph is
62	// sanitized (ANSI/control stripped) and wrapped independently. A paragraph that
63	// wraps to nothing still contributes an empty line, preserving blank-line
64	// structure between paragraphs.
65	//
66	// Returns nil for width <= 0 or empty input.
67	func wrapDisplayWidth(s string, width int) []string {
68		if width <= 0 || s == "" {
69			return nil
70		}
71		paragraphs := strings.Split(s, "\n")
72		out := make([]string, 0, len(paragraphs))
73		for _, p := range paragraphs {
74			clean := sanitizeDisplayText(p)
75			if clean == "" {
76				out = append(out, "")
77				continue
78			}
79			wrapped := ansi.Wrap(clean, width, "")
80			out = append(out, strings.Split(wrapped, "\n")...)
81		}
82		return out
83	}
